const pricing = {
  "tostem windows": { unit: "sq.ft", price: 650, category: "Windows" },
  "tostem doors": { unit: "sq.ft", price: 900, category: "Doors" },
  "ultrafresh kitchen": { unit: "sq.ft", price: 2200, category: "Kitchen" },
  "mikasa engineered wood": { unit: "sq.ft", price: 350, category: "Flooring" },
  "mikasa laminate": { unit: "sq.ft", price: 220, category: "Flooring" },
  "welspun lvt": { unit: "sq.ft", price: 180, category: "Flooring" },
  "welspun spc": { unit: "sq.ft", price: 200, category: "Flooring" }
};

const productKey = String(query.product || "").trim().toLowerCase();
const match = pricing[productKey];

if (!match) {
  return JSON.stringify({
    error: true,
    message: `No mock price found for "${query.product}". Available products: ${Object.keys(pricing).join(", ")}`
  });
}

const area = Number(query.area_sqft);
if (!area || area <= 0) {
  return JSON.stringify({ error: true, message: "area_sqft must be a positive number." });
}

const includeWastage = query.include_wastage !== false;
const materialCost = area * match.price;
const wastage = includeWastage ? materialCost * 0.05 : 0;
const total = materialCost + wastage;

return JSON.stringify({
  product: query.product,
  category: match.category,
  area_sqft: area,
  mock_price_per_sqft: match.price,
  material_cost: Math.round(materialCost),
  wastage_included: includeWastage,
  wastage_amount: Math.round(wastage),
  estimated_total: Math.round(total),
  disclaimer: "Mock average price for prototype demonstration — not an actual quotation."
});

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "product": {
      "type": "string",
      "description": "Product name, must match one of: Tostem Windows, Tostem Doors, Ultrafresh Kitchen, Mikasa Engineered Wood, Mikasa Laminate, Welspun LVT, Welspun SPC"
    },
    "area_sqft": {
      "type": "number",
      "description": "Total area in square feet"
    },
    "include_wastage": {
      "type": "boolean",
      "description": "Whether to add 5% wastage buffer, default true"
    }
  },
  "required": ["product", "area_sqft"]
}
